prog='''from collections import Counter

def _blocks(g):
    bg = Counter(x for r in g for x in r).most_common(1)[0][0]
    rows = [r for r in range(len(g)) if any(x != bg for x in g[r])]
    bl, cur = [], [rows[0]]
    for r in rows[1:]:
        if r == cur[-1] + 1:
            cur.append(r)
        else:
            bl.append(cur); cur = [r]
    bl.append(cur)
    return bg, bl

def transform(grid):
    g = [r[:] for r in grid]
    bg, bl = _blocks(g)
    w = len(g[0])
    if len(bl) != 2 or len(bl[0]) != len(bl[1]):
        return g

    def lastobj(r):
        return max((c for c in range(w) if g[r][c] != bg), default=-1)

    def score(copy, ref, s):
        m = mm = 0
        for c in range(w):
            cs = c - s
            if 0 <= cs < w:
                if g[copy][c] != bg and g[ref][cs] != bg:
                    if g[copy][c] == g[ref][cs]:
                        m += 1
                    else:
                        mm += 1
                elif g[copy][c] != bg and g[ref][cs] == bg:
                    mm += 1
        return m - mm

    for ra, rb in zip(bl[0], bl[1]):
        cands = []
        for (copy, ref, s) in ((ra, rb, 1), (rb, ra, 1), (ra, rb, 0)):
            cands.append((score(copy, ref, s), copy, ref, s))
        best = max(cands)[0]
        good = [c for c in cands if c[0] == best]
        good.sort(key=lambda c: lastobj(c[1]) - lastobj(c[2]))
        _, copy, ref, s = good[0]
        L, LR = lastobj(copy), lastobj(ref)
        if L < LR:
            aligned = L - s
            for p in range(LR, aligned, -1):
                if g[ref][p] != bg:
                    c = p + s
                    if 0 <= c < w:
                        out[copy][c] = 1
    return g
'''
